contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 baseAmount, uint256 quoteAmount) public payable {
        // this call is made directly on c, but C has no public mint/receive for funding;
        // we use the precondition that c already holds enough base tokens via its public reserve path.
        require(baseAmount > 0, "need base input");

        uint256 reserve = uint256(c._BASE_RESERVE_());
        uint256 supplyBefore = c.totalSupply();

        try c.buyShares(address(this)) returns (
            uint256 shares,
            uint256 baseInput,
            uint256 quoteInput
        ) {
            uint256 supplyAfter = c.totalSupply();
            uint256 reserveAfter = uint256(c._BASE_RESERVE_());

            assert(
                supplyAfter - supplyBefore == shares &&
                reserveAfter - reserve == baseInput
            );
        } catch {
            revert("buyShares reverted");
        }
    }

    receive() external payable {}
}

