contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 baseAmount, uint256 quoteAmount) public payable {
        // Precondition: both token amounts are positive
        require(baseAmount > 0, "baseAmount must be positive");
        require(quoteAmount > 0, "quoteAmount must be positive");

        // Record reserves before any actions
        uint256 baseReserveBefore = c._BASE_RESERVE_();
        uint256 quoteReserveBefore = c._QUOTE_RESERVE_();

        // Only test when the pool is already initialized (non-empty reserves)
        require(baseReserveBefore > 0 && quoteReserveBefore > 0, "pool must be non-empty");

        // Read balances of this test contract to ensure enough tokens
        IERC20 baseToken = c._BASE_TOKEN_();
        IERC20 quoteToken = c._QUOTE_TOKEN_();
        require(baseToken.balanceOf(address(this)) >= baseAmount, "not enough base tokens");
        require(quoteToken.balanceOf(address(this)) >= quoteAmount, "not enough quote tokens");

        // Transfer tokens to the pool (pre-buy input)
        baseToken.transfer(address(c), baseAmount);
        quoteToken.transfer(address(c), quoteAmount);

        // Execute buyShares
        c.buyShares(address(this));

        // Read reserves after the buy
        uint256 baseReserveAfter = c._BASE_RESERVE_();
        uint256 quoteReserveAfter = c._QUOTE_RESERVE_();

        // General rule: the sum of reserves increases by exactly the input amounts
        assert(baseReserveAfter + quoteReserveAfter == baseReserveBefore + quoteReserveBefore + baseAmount + quoteAmount);
    }

    receive() external payable {}
}

