contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 baseAmount, uint256 quoteAmount) public payable {
        require(baseAmount > 0, "need base input");
        require(address(this).balance >= 0, "balance ok");

        // Seed the contract with tokens so that buyShares has an input.
        // We cannot mint tokens ourselves, so we use the fact that the test contract
        // already holds tokens if they were transferred to it before run() was called.
        // For a property test, we assume the setup provides balances; here we only
        // check the property when the call does not revert due to missing tokens.
        // However, to make the property meaningful and reachable, we need some tokens.
        // We cannot call token.transfer without an interface, so we rely on the checker
        // to have pre-funded this test contract with tokens. The property is conditional
        // on the call not reverting.

        // Read total supply before the call.
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        uint256 shares;
        uint256 baseInput;
        uint256 quoteInput;

        try c.buyShares(address(this)) returns (uint256 s, uint256 b, uint256 q) {
            shares = s;
            baseInput = b;
            quoteInput = q;
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if buyShares succeeds when totalSupply was zero, it must have
        // minted at least 2001 shares (1001 burned to zero address + at least 1000 to caller).
        // Additionally, totalSupply must increase by exactly shares.
        if (!reverted && totalSupplyBefore == 0) {
            assert(shares >= 2001);
        }
        // Always: totalSupply after must be totalSupplyBefore + shares (if not reverted).
        if (!reverted) {
            assert(c.totalSupply() == totalSupplyBefore + shares);
        }
    }

    receive() external payable {}
}

